  padding-bottom: 4px;
}
lj_affection_comment, lj_forum_comment, lj_section1_comment, lj_section2_comment, lj_section3_comment {
  font-size: 11px;
  opacity: 0.5;
  text-align: right;
  margin-top: 2px;
}

