:root {
/* 铺满高清底图 */
--tm-bg-image: url('https://pic.82314912.xyz/api/cfile/AgACAgEAAyEGAATEcCnBAAKKJ2rFKvQPXyhMw94-SRaA3J_1dJ2xAALgDGsbT-YoRg0eHPItXg_kAQADAgADdwADPQQ');
--tm-bg-size: cover;
--tm-bg-position: center;
/* 顶部透明 */
--tm-header-bg: transparent;
--tm-header-border: none;
}
/* 底部输入区全透 */
.tm-compose {
background: transparent !important;
border: none !important;
backdrop-filter: none !important;
}
/* 输入框保留一点毛玻璃，防止找不到在哪打字 */
.tm-input {
background: rgba(255,255,255,0.2) !important;
backdrop-filter: blur(8px) !important;
-webkit-backdrop-filter: blur(8px) !important;
border: 1px solid rgba(255,255,255,0.3) !important;
}
/* AI消息头像：不规则水滴艺术感 */
.tm-msg-avatar {
border-radius: 30% 70% 70% 30% / 30% 30% 70% 70% !important;
border: 2px solid rgba(255,255,255,0.6) !important;
box-shadow: 2px 2px 8px rgba(0,0,0,0.15) !important;
}
/* 题头学生证样式：竖版比例 + 粗白边 */
.tm-header-avatar {
width: 32px !important;
height: 46px !important;
border-radius: 4px !important;
border: 2px solid #fff !important;
box-shadow: 0 3px 8px rgba(0,0,0,0.2) !important;
position: relative !important;
overflow: visible !important;
}
/* 学生证顶部的金属小夹子 */
.tm-header-avatar::after {
content: "";
position: absolute;
top: -6px;
left: 50%;
transform: translateX(-50%);
width: 12px;
height: 5px;
background: linear-gradient(to bottom, #eee, #999);
border-radius: 2px;
box-shadow: 0 1px 2px rgba(0,0,0,0.3);
}

